// Parse the queue: every `- [ ]` / `- [x]` line that references a blog or
// glossary URL is one queue item. Returns { blog, glossary } slug sets plus
// posted/total counts.
function parseQueue(markdown) {
  const blog = new Set();
  const glossary = new Set();
  let total = 0;
  let posted = 0;
  const checkbox = /^\s*-\s*\[( |x|X)\]\s*(.*)$/;
  const link = /agilepainrelief\.com\/(blog|glossary)\/([a-z0-9_-]+)/i;
  for (const line of markdown.split("\n")) {
    const m = checkbox.exec(line);
    if (!m) continue;
    const l = link.exec(m[2]);
    if (!l) continue;
    total += 1;
    if (m[1].toLowerCase() === "x") posted += 1;
    (l[1].toLowerCase() === "blog" ? blog : glossary).add(l[2]);
